<?php
use Moves\Services\{BankReconciliation,Finance,FinanceContext};$e=static fn($v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$lines=$accounts=[];$error=null;try{$finance=new Finance((int)FinanceContext::currentId());$accounts=array_values(array_filter($finance->accounts(),static fn($a)=>$a['type']!=='credit_card'));$lines=(new BankReconciliation((int)FinanceContext::currentId()))->lines();}catch(Throwable $x){error_log('Realizze reconciliation: '.$x->getMessage());$error='A estrutura de conciliação ainda precisa da migration 014.';}$flash=$_SESSION['finance_flash']??null;unset($_SESSION['finance_flash']); ?>
<?php if(is_array($flash)): ?><p class="finance-flash finance-flash-<?= $e($flash[0]) ?>" role="status"><?= $e($flash[1]) ?></p><?php endif; ?><section class="card finance-workspace"><div class="finance-toolbar"><div><h2>Conciliação bancária</h2><p class="muted">Importe o extrato para revisar. Nenhuma linha altera saldo ou cria lançamento automaticamente.</p></div><button type="button" class="primary" data-finance-open="statement-import">Importar CSV</button></div><?php if($error): ?><div class="finance-empty"><h3>Módulo aguardando atualização</h3><p><?= $e($error) ?></p></div><?php elseif($lines===[]): ?><div class="finance-empty"><h3>Nenhuma linha para revisar</h3><p>Importe um CSV com as colunas Data, Descrição e Valor.</p></div><?php else: ?><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Data</th><th>Descrição</th><th>Conta</th><th class="num">Valor</th><th>Situação</th><th></th></tr></thead><tbody><?php foreach($lines as $line): ?><tr><td><?= $e((new DateTimeImmutable($line['occurred_on']))->format('d/m/Y')) ?></td><td><?= $e($line['description']) ?></td><td><?= $e($line['account']) ?></td><td class="num <?= (int)$line['amount_cents']<0?'red':'green' ?>"><?= $e(Finance::money((int)$line['amount_cents'])) ?></td><td><?= $e(['pending'=>'Pendente','matched'=>'Conciliada','ignored'=>'Ignorada','reversed'=>'Estornada'][$line['status']]??$line['status']) ?></td><td><?php if($line['status']==='pending'): ?><form method="post" action="/minha-conta/financeiro/conciliacao-revisar" data-finance-confirm="Ignorar esta linha?"><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="back" value="conciliacao"><input type="hidden" name="line_id" value="<?= (int)$line['id'] ?>"><input type="hidden" name="status" value="ignored"><button>Ignorar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><dialog class="finance-dialog" id="statement-import"><form method="post" enctype="multipart/form-data" action="/minha-conta/financeiro/conciliacao-importar"><header><h2>Importar extrato CSV</h2><button type="button" data-finance-close>×</button></header><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="back" value="conciliacao"><label>Conta<select name="account_id" required><?php foreach($accounts as $a): ?><option value="<?= (int)$a['id'] ?>"><?= $e($a['name']) ?></option><?php endforeach; ?></select></label><label>Arquivo CSV (máx. 5 MB)<input type="file" name="statement" accept=".csv,text/csv" required></label><p class="muted">Use cabeçalho: Data; Descrição; Valor. A importação requer confirmação por item.</p><footer><button type="button" data-finance-close>Cancelar</button><button class="primary"<?= $accounts===[]?' disabled':'' ?>>Enviar para revisão</button></footer></form></dialog>
